  },
  {
   "metric": "margin",
   "statement": "CaratLane EBIT margins should gradually start inching up from 8% to 9% and further.",
   "quote": "still remains as per our plan that gradually their EBIT margin should start inching up from 8% to 9%, and then further from there in next couple of years.",
   "page": 4,
   "horizon": "next couple of years",
   "quantitative": true
  }
 ],
